const identity=(row:Delegated500DataIdentity)=>row.city+'|'+row.objectId+'|'+row.partId;
export function delegatedSourceContext(input:readonly Delegated500DataIdentity[]){
 const rows=new Map(input.map(row=>[identity(row),row])),matched=new Set<string>();
 for(let changed=true;changed;){changed=false;
  for(const row of delegated500DemandClosure([...rows.values()]).identities)if(!rows.has(identity(row))){rows.set(identity(row),row);changed=true;}
  for(const group of DELEGATED_SOURCE_CONTEXT_GROUPS){if(!group.identities.some(row=>rows.has(identity(row))))continue;matched.add(group.module);for(const row of group.identities)if(!rows.has(identity(row))){rows.set(identity(row),row);changed=true;}}
 }
 return{identities:[...rows.values()],authority:['delegated500-source-context-v1',DELEGATED_DATA_DEMAND_SHA256,DELEGATED_SOURCE_CONTEXT_GROUPS.filter(group=>matched.has(group.module)).map(group=>[group.module,group.sourceSHA256])]};
}

/** Join only actual already-resident contributors. Declared but absent source
 * identities remain absent: this resolver never requests or invents a group. */
export function resolveDelegatedSourceContext<T extends Delegated500DataIdentity,G extends {contentKey:string;components:readonly T[]}>(input:readonly T[],groups:readonly G[]){
 const context=delegatedSourceContext(input),wanted=new Set(context.identities.map(identity)),contributors=[...groups].filter(group=>group.components.some(row=>wanted.has(identity(row)))).sort((a,b)=>a.contentKey.localeCompare(b.contentKey));
 return{authority:context.authority,contributors,components:contributors.flatMap(group=>group.components.filter(row=>wanted.has(identity(row))))};
}
